import {assertSaveWrite} from './expedition-save-ownership.mjs';
import {validateArchivePayloads} from './expedition-report-archive.mjs';
import {GUILD_KEY,newGuild,validateGuild} from './expedition-guild.mjs';import {defaults,clone} from './expedition-data.mjs';import {validate,RULESET} from './expedition-engine.mjs';import {readPlanBook,encodePlanBook} from './expedition-plan-book.mjs';
export const CAMPAIGN_KEYS=['abbey-expedition-v40','abbey-plan-library-v1','abbey-expedition-v40-a',GUILD_KEY];
const exact=(o,ks)=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).sort().join(',')===[...ks].sort().join(',');
export function campaignRaw(storage){return Object.fromEntries(CAMPAIGN_KEYS.map(k=>[k,storage.getItem(k)]));}
function validatePayload(p){if(!exact(p,['createdAt','ruleset','guild','preparation','plans','comparison',...(Object.hasOwn(p||{},'planBindings')?['planBindings']:[])])||typeof p.createdAt!=='string'||!Number.isFinite(Date.parse(p.createdAt))||p.ruleset!==RULESET)throw Error('整档备份格式或规则无效');validateGuild(p.guild);validate(p.preparation);if(p.comparison!==null)validate(p.comparison);readPlanBook(JSON.stringify({version:1,plans:p.plans,...(Object.hasOwn(p,'planBindings')?{bindings:p.planBindings}:{})}));for(const plan of p.plans)validate(plan.config);return p;}
const digest=async p=>{if(!globalThis.crypto?.subtle)throw Error('当前页面无法执行文件校验，请使用本机或HTTPS地址');return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(p))))).map(b=>b.toString(16).padStart(2,'0')).join('');};
export async function captureCampaign(storage,createdAt=new Date().toISOString()){const raw=campaignRaw(storage),book=readPlanBook(raw[CAMPAIGN_KEYS[1]]),payload={createdAt,ruleset:RULESET,guild:raw[GUILD_KEY]===null?newGuild():JSON.parse(raw[GUILD_KEY]),preparation:raw[CAMPAIGN_KEYS[0]]===null?defaults():JSON.parse(raw[CAMPAIGN_KEYS[0]]),plans:book.plans,...(Object.keys(book.bindings).length?{planBindings:book.bindings}:{}),comparison:raw[CAMPAIGN_KEYS[2]]===null?null:JSON.parse(raw[CAMPAIGN_KEYS[2]])};validatePayload(payload);await validateArchivePayloads(payload.guild.reportArchives);const checksum=await digest(payload);if(CAMPAIGN_KEYS.some(k=>storage.getItem(k)!==raw[k]))throw Error('导出期间本机内容已变化，请重新导出');return {format:'wod-campaign',version:1,payload,checksum};}
export async function validateCampaignBackup(b){if(!exact(b,['format','version','payload','checksum'])||b.format!=='wod-campaign'||b.version!==1||typeof b.checksum!=='string'||!/^[0-9a-f]{64}$/.test(b.checksum))throw Error('不是有效的整档备份');if(await digest(b.payload)!==b.checksum)throw Error('整档校验和不匹配，文件可能损坏；未恢复任何内容');validatePayload(b.payload);await validateArchivePayloads(b.payload.guild.reportArchives);return clone(b.payload);}
export async function restoreCampaign(storage,backup,expected){const p=await validateCampaignBackup(backup);assertSaveWrite(storage);if(!exact(expected,CAMPAIGN_KEYS)||CAMPAIGN_KEYS.some(k=>storage.getItem(k)!==expected[k]))throw Error('预览后本机内容已变化，请重新选择备份并核对；未覆盖');const next={[CAMPAIGN_KEYS[0]]:JSON.stringify(p.preparation),[CAMPAIGN_KEYS[1]]:encodePlanBook({version:1,plans:p.plans,bindings:p.planBindings||{}}),[CAMPAIGN_KEYS[2]]:p.comparison===null?null:JSON.stringify(p.comparison),[GUILD_KEY]:JSON.stringify(p.guild)},written=[];
 try{for(const k of CAMPAIGN_KEYS){if(next[k]===null)storage.removeItem(k);else storage.setItem(k,next[k]);written.push(k);}}
 catch(error){const failed=[];for(const k of written.reverse())try{if(expected[k]===null)storage.removeItem(k);else storage.setItem(k,expected[k]);}catch(e){failed.push(k+': '+e.message);}if(failed.length)throw Error('整档保存失败且部分回退失败，请导出本机原始内容后检查存储：'+failed.join('；'));throw Error('整档保存失败，已回退全部已写入项目：'+error.message);}return p;
}
